import os, glob, docx, openpyxl, pymupdf, subprocess

base = '/filesystem/final_batch4__mechanical_task5_pcw_flush_mop__blind'

def read_docx(p):
    doc = docx.Document(p)
    lines = []
    for para in doc.paragraphs:
        if para.text.strip():
            lines.append(para.text)
    for t in doc.tables:
        for row in t.rows:
            lines.append(' | '.join(c.text.strip().replace('\n', ' ') for c in row.cells))
    return '\n'.join(lines)

for folder in ['specs', 'site', 'correspondence']:
    for p in sorted(glob.glob(os.path.join(base, folder, '*.docx'))):
        print('====================================')
        print('FILE:', os.path.relpath(p, base))
        print('====================================')
        print(read_docx(p))
